              if (status === 'authenticated')
                void save
                  .mutateAsync({ interests: experience.interests, goal: experience.goal })
                  .then(() => router.replace('/'))
                  .catch(() => {});
              else void finish('/login');
            } else go(step + 1);
          }}

{() => {
              if (status !== 'authenticated' && step === 9) void finish('/register');
              else if (required) go(step + 1);
              else if (step === 1) router.push('/login');
              else if (step <= 3) go(5);
              else if (step === 4 || step === 9) router.replace('/');
              else go(step + 1);
            }}
